.hero {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  background: linear-gradient(160deg, var(--color-bg) 0%, #1a1025 50%, var(--color-bg) 100%);
  position: relative;
  overflow: hidden;
}

.hero::before {
  content: "";
  position: absolute;
  top: 20%;
  left: 50%;
  transform: translateX(-50%);
  width: 600px;
  height: 600px;
  background: radial-gradient(circle, rgba(167, 139, 250, 0.15) 0%, transparent 70%);
  pointer-events: none;
}

.hero__inner {
  position: relative;
  z-index: 1;
  max-width: 720px;
  padding: 2rem;
}

.hero__brand {
  display: inline-block;
  font-family: var(--font-heading);
  font-size: 0.875rem;
  font-weight: 600;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--color-accent);
  margin-bottom: 1.5rem;
}

.hero__heading {
  font-family: var(--font-heading);
  font-size: clamp(2.5rem, 6vw, 4.5rem);
  font-weight: 700;
  line-height: 1.1;
  color: var(--color-text);
  margin: 0 0 1.5rem;
  letter-spacing: -0.02em;
}

.hero__subheading {
  font-family: var(--font-body);
  font-size: clamp(1rem, 2vw, 1.25rem);
  line-height: 1.7;
  color: var(--color-text-muted);
  margin: 0 0 2rem;
  max-width: 560px;
  margin-left: auto;
  margin-right: auto;
}

.hero__launch-date {
  margin-top: 2.5rem;
}

.hero__launch-pill {
  display: inline-block;
  padding: 0.625rem 1.5rem;
  border: 1px solid rgba(167, 139, 250, 0.3);
  border-radius: 9999px;
  font-family: var(--font-body);
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--color-accent);
  letter-spacing: 0.05em;
  background: rgba(167, 139, 250, 0.08);
}

.features-preview {
  padding: 6rem 2rem;
  background: var(--color-bg);
}

.features-preview__inner {
  max-width: 1080px;
  margin: 0 auto;
}

.features-preview__title {
  font-family: var(--font-heading);
  font-size: clamp(1.75rem, 4vw, 2.5rem);
  font-weight: 700;
  color: var(--color-text);
  text-align: center;
  margin: 0 0 3.5rem;
  letter-spacing: -0.02em;
}

.features-preview__grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1.5rem;
}

.features-preview__card {
  background: rgba(255, 255, 255, 0.04);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border: 1px solid rgba(255, 255, 255, 0.06);
  border-radius: 1rem;
  padding: 2rem;
  transition: transform 0.2s ease, border-color 0.2s ease;
}

.features-preview__card:hover {
  transform: translateY(-4px);
  border-color: rgba(167, 139, 250, 0.25);
}

.features-preview__icon {
  display: block;
  font-size: 2rem;
  margin-bottom: 1rem;
}

.features-preview__card-title {
  font-family: var(--font-heading);
  font-size: 1.125rem;
  font-weight: 600;
  color: var(--color-text);
  margin: 0 0 0.75rem;
}

.features-preview__card-desc {
  font-family: var(--font-body);
  font-size: 0.9375rem;
  line-height: 1.6;
  color: var(--color-text-muted);
  margin: 0;
}

@media (max-width: 768px) {
  .features-preview__grid {
    grid-template-columns: 1fr;
    gap: 1rem;
  }
}

.signup {
  padding: 6rem 2rem;
  background: linear-gradient(180deg, var(--color-bg) 0%, #110d1a 100%);
}

.signup__inner {
  max-width: 560px;
  margin: 0 auto;
  text-align: center;
}

.signup__heading {
  font-family: var(--font-heading);
  font-size: clamp(1.75rem, 4vw, 2.5rem);
  font-weight: 700;
  color: var(--color-text);
  margin: 0 0 1rem;
  letter-spacing: -0.02em;
}

.signup__description {
  font-family: var(--font-body);
  font-size: 1.0625rem;
  line-height: 1.6;
  color: var(--color-text-muted);
  margin: 0 0 2.5rem;
}

.signup__form-embed {
  margin-top: 1rem;
}

.signup__placeholder {
  margin-top: 1rem;
}

.signup__input-group {
  display: flex;
  gap: 0;
  max-width: 440px;
  margin: 0 auto;
  border-radius: 0.75rem;
  overflow: hidden;
  border: 1px solid rgba(167, 139, 250, 0.2);
}

.signup__fake-input {
  flex: 1;
  padding: 0.875rem 1.25rem;
  background: rgba(255, 255, 255, 0.04);
  color: var(--color-text-muted);
  font-family: var(--font-body);
  font-size: 0.9375rem;
  text-align: left;
  border: none;
}

.signup__button {
  padding: 0.875rem 1.75rem;
  background: var(--color-accent);
  color: #09090b;
  font-family: var(--font-heading);
  font-size: 0.9375rem;
  font-weight: 600;
  border: none;
  cursor: pointer;
  white-space: nowrap;
  transition: background 0.2s ease;
}

.signup__button:hover {
  background: #8b6ff0;
}

.signup__hint {
  font-family: var(--font-body);
  font-size: 0.8125rem;
  color: var(--color-text-muted);
  margin: 1.25rem 0 0;
  opacity: 0.7;
}

@media (max-width: 480px) {
  .signup__input-group {
    flex-direction: column;
    border-radius: 0.75rem;
  }

  .signup__fake-input {
    text-align: center;
    border-bottom: 1px solid rgba(167, 139, 250, 0.1);
  }

  .signup__button {
    border-radius: 0;
  }
}

sharedCss:
:root {
  --color-bg: #09090b;
  --color-surface: #18181b;
  --color-accent: #a78bfa;
  --color-text: #fafafa;
  --color-text-muted: #71717a;
  --font-heading: system-ui, sans-serif;
  --font-body: system-ui, sans-serif;
}

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background-color: var(--color-bg);
  color: var(--color-text);
  font-family: var(--font-body);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}
